insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_fashionable','fashionable','adjective','popular and stylish at a particular time','[{"senseId":"fashionable_1","meaning":"popular and stylish at a particular time","acceptedParaphrases":["trendy","in style"],"masteryContexts":[{"contextId":"u3_31_fashionable_meaning","text":"It is fashionable to eat plant-based food, and many new cafes now offer vegan menus.","meaning":"popular at the present time","wrongMeanings":["expensive and hard to find","healthy and good for the body","simple and cheap to make"]},{"contextId":"u3_31_fashionable_paraphrase","text":"The fashionable restaurant on the harbour is always full of young people who want to be seen there.","meaning":"popular and stylish","wrongMeanings":["old and no longer used","quiet and far from the city","large and cheap"]}],"situationDistractors":["Nobody visits the old cafe, and its menu has not changed since 1980.","The restaurant is empty, and young people say it looks dull and out of date.","The shop sells plain, practical lunch boxes that people have used for years.","The market stall sells local vegetables at low prices.","The cafe closes early on Sundays.","The chef learned the recipe from his grandmother."],"gapDistractors":[{"contextId":"u3_31_fashionable_gap_1","answer":"fashionable","wrong":["punctual","generous","nervous"]},{"contextId":"u3_31_fashionable_gap_2","answer":"fashionable","wrong":["remote","dull","peaceful"]},{"contextId":"u3_31_fashionable_gap_3","answer":"fashionable","wrong":["punctual","tired","shy"]}],"spellingErrors":["fashonable","fasionable","fashionible","fashinable","fashionnable","fashionabel"],"wordFamilyForms":[{"form":"fashionable","partOfSpeech":"adjective","example":"Bubble tea is a fashionable drink among teenagers in the city.","pedagogicallyUseful":true},{"form":"fashion","partOfSpeech":"noun","example":"Restaurant menus often follow fashion, so dishes that were popular last year may disappear.","pedagogicallyUseful":true,"altExample":"A new fashion for tiny cafes has appeared in the city centre."},{"form":"unfashionable","partOfSpeech":"adjective","example":"Five years ago, kale was unfashionable, but now it appears on many menus.","pedagogicallyUseful":true,"altExample":"Many people think that boiled vegetables are unfashionable today."}],"masteryPassages":[{"passageId":"u3_31_fashionable_passage_1","contextId":"u3_31_fashionable_gap_1","text":"A few years ago, nobody drank green juice. Now it is ____ among young people, and every cafe on the main street sells it.","answer":"fashionable"},{"passageId":"u3_31_fashionable_passage_2","contextId":"u3_31_fashionable_gap_2","text":"Mei wanted to take her friends somewhere new and exciting. She chose a ____ restaurant with bright lights and a famous chef, even though it was expensive.","answer":"fashionable"}],"contextDependentParaphrases":[],"wrongParaphrases":["traditional","unpopular","affordable"],"misleadingDistractors":["cheap and easy to find","old and traditional","plain and practical"]}]'::jsonb,'["fashion","unfashionable"]'::jsonb,'["highly fashionable","become fashionable","fashionable restaurant"]'::jsonb,'live'),
('vocab_satisfying','satisfying','adjective','pleasing because it gives you what you wanted or needed','[{"senseId":"satisfying_1","meaning":"pleasing because it gives you what you wanted or needed","acceptedParaphrases":["pleasing","rewarding"],"masteryContexts":[{"contextId":"u3_32_satisfying_meaning","text":"After the long hike, the hot noodle soup was warm, filling and very satisfying.","meaning":"pleasing because it gave what was needed","wrongMeanings":["causing worry because it was not enough","difficult to swallow because it was dry","too hot to eat quickly"]},{"contextId":"u3_32_satisfying_paraphrase","text":"It is satisfying to see customers enjoy a meal that you have cooked yourself.","meaning":"giving a pleasant feeling of success","wrongMeanings":["annoying to see because of the noise","tiring to do because of the crowd","difficult to see because of the light"]}],"situationDistractors":["The soup was cold and tasted of nothing, and we left most of it.","The portion was so small that we were still hungry after dessert.","The waiter forgot our order twice, and the bill was wrong.","The cafe opens at eight and closes at six.","The chef wore a white hat and an apron.","There were four tables near the window."],"gapDistractors":[{"contextId":"u3_32_satisfying_gap_1","answer":"satisfying","wrong":["confusing","tiring","worrying"]},{"contextId":"u3_32_satisfying_gap_2","answer":"satisfying","wrong":["disappointing","annoying","worrying"]},{"contextId":"u3_32_satisfying_gap_3","answer":"satisfying","wrong":["unfair","confusing","noisy"]}],"spellingErrors":["satisfiing","satisfyng","satisfing","satsfying","satisfieing","satysfying"],"wordFamilyForms":[{"form":"satisfying","partOfSpeech":"adjective","example":"A bowl of hot soup is satisfying after a long walk in the cold.","pedagogicallyUseful":true},{"form":"satisfy","partOfSpeech":"verb","example":"One small sandwich will not satisfy a hungry teenager after sport.","pedagogicallyUseful":true},{"form":"satisfied","partOfSpeech":"adjective","example":"The customers were satisfied with the service and left a generous tip.","pedagogicallyUseful":true},{"form":"satisfaction","partOfSpeech":"noun","example":"Many cooks say that the greatest satisfaction comes from seeing guests enjoy their food.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u3_32_satisfying_passage_1","contextId":"u3_32_satisfying_gap_1","text":"We walked for five hours in the rain, and we were cold, wet and hungry. The hot rice and chicken that the hotel served us afterwards were simple, but ____.","answer":"satisfying"},{"passageId":"u3_32_satisfying_passage_2","contextId":"u3_32_satisfying_gap_2","text":"Anna spent all afternoon baking bread for the first time. When she cut the warm loaf and everyone said it was delicious, she found the whole experience deeply ____.","answer":"satisfying"}],"contextDependentParaphrases":[],"wrongParaphrases":["disappointing","worrying","tiring"],"misleadingDistractors":["causing worry because it is not enough","needing a lot of time and effort","costing more than expected"]}]'::jsonb,'["satisfy","satisfied","satisfaction"]'::jsonb,'["deeply satisfying","satisfying meal","very satisfying"]'::jsonb,'live'),
('vocab_reasonable_3','reasonable','adjective','fair and sensible, not too extreme','[{"senseId":"reasonable_3_1","meaning":"fair and sensible, not too extreme","acceptedParaphrases":["fair","sensible"],"masteryContexts":[{"contextId":"u3_33_reasonable_3_meaning","text":"The cafe serves large portions at a reasonable price, so it is popular with students.","meaning":"fair and not too high","wrongMeanings":["very low and of poor quality","far too high for most people","different every week"]},{"contextId":"u3_33_reasonable_3_paraphrase","text":"It is reasonable to expect hot food to arrive hot, so her complaint was fair.","meaning":"sensible and fair to expect","wrongMeanings":["strange and hard to believe","rude and unkind to say","secret and not for sharing"]}],"situationDistractors":["The bill came to three times the price on the menu, and nobody could explain why.","The waiter shouted at the customer for asking a simple question.","The restaurant demanded a deposit of two hundred pounds for a cup of tea.","The menu was written in a language that none of the guests could read.","He refused to listen to any opinion except his own.","The cafe closed for the afternoon."],"gapDistractors":[{"contextId":"u3_33_reasonable_3_gap_1","answer":"reasonable","wrong":["sudden","secret","loud"]},{"contextId":"u3_33_reasonable_3_gap_2","answer":"reasonable","wrong":["impossible","unlucky","careless"]},{"contextId":"u3_33_reasonable_3_gap_3","answer":"reasonable","wrong":["selfish","dishonest","dangerous"]}],"spellingErrors":["reasonible","resonable","reasonnable","reasonabal","reasenable","reasonble"],"wordFamilyForms":[{"form":"reasonable","partOfSpeech":"adjective","example":"Her complaint was reasonable, because the soup really was cold.","pedagogicallyUseful":true},{"form":"reasonably","partOfSpeech":"adverb","example":"The soup was reasonably hot, so we ate it before it cooled.","pedagogicallyUseful":true,"altExample":"The pasta was reasonably good, but the sauce was too salty."},{"form":"unreasonable","partOfSpeech":"adjective","example":"It is unreasonable to expect a fast meal in a crowded restaurant.","pedagogicallyUseful":true,"altExample":"The customer made an unreasonable demand when he asked for a free meal."}],"masteryPassages":[{"passageId":"u3_33_reasonable_3_passage_1","contextId":"u3_33_reasonable_3_gap_1","text":"The restaurant was not the cheapest in town, but the food was of a high quality. Considering the size of the meals, most customers agreed that the price was ____.","answer":"reasonable"},{"passageId":"u3_33_reasonable_3_passage_2","contextId":"u3_33_reasonable_3_gap_2","text":"Daniel complained that his soup was cold, and the waiter replaced it quickly. It was a ____ request, because anyone would expect hot soup.","answer":"reasonable"}],"contextDependentParaphrases":[],"wrongParaphrases":["absurd","selfish","costly"],"misleadingDistractors":["very cheap and of poor quality","strange and difficult to believe","extreme and unfair to others"],"teacherNote":"Unit 3 item (reasonable_3), separate from Unit 1 reasonable; shares only the lexical spelling list."}]'::jsonb,'["reasonably","unreasonable"]'::jsonb,'["reasonable price","perfectly reasonable","reasonable request"]'::jsonb,'live'),
('vocab_disappointed','disappointed','adjective','unhappy because something was not as good as you hoped','[{"senseId":"disappointed_1","meaning":"unhappy because something was not as good as you hoped","acceptedParaphrases":["let down","unhappy with the result"],"masteryContexts":[{"contextId":"u3_34_disappointed_meaning","text":"Customers were disappointed when the restaurant ran out of their favourite dish.","meaning":"unhappy because things were not as hoped","wrongMeanings":["angry because the staff were rude","worried because the food was unsafe","surprised because the dish was free"]},{"contextId":"u3_34_disappointed_paraphrase","text":"She felt disappointed with the service, because the waiter forgot her order twice.","meaning":"let down because expectations were not met","wrongMeanings":["tired because the day was long","happy because the food was ready","nervous because the room was full"]}],"situationDistractors":["The meal arrived quickly, and every dish tasted wonderful.","The family left the restaurant delighted by the friendly service.","He was thrilled when the chef brought a free dessert.","The waiter wiped the table and brought the menus.","The queue outside the cafe moved quickly.","She ordered tea and a slice of lemon cake."],"gapDistractors":[{"contextId":"u3_34_disappointed_gap_1","answer":"disappointed","wrong":["delighted","grateful","excited"]},{"contextId":"u3_34_disappointed_gap_2","answer":"disappointed","wrong":["grateful","pleased","proud"]},{"contextId":"u3_34_disappointed_gap_3","answer":"disappointed","wrong":["grateful","pleased","proud"]}],"spellingErrors":["dissapointed","disapointed","disappointd","disappoinded","dissapoited","disappointted"],"wordFamilyForms":[{"form":"disappointed","partOfSpeech":"adjective","example":"We were disappointed by the soup, which was cold and tasted of nothing.","pedagogicallyUseful":true},{"form":"disappoint","partOfSpeech":"verb","example":"I do not want to disappoint my guests, so I will check the recipe again.","pedagogicallyUseful":true},{"form":"disappointing","partOfSpeech":"adjective","example":"The service was slow and the food was disappointing.","pedagogicallyUseful":true},{"form":"disappointment","partOfSpeech":"noun","example":"To her disappointment, the cafe was closed on Mondays.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u3_34_disappointed_passage_1","contextId":"u3_34_disappointed_gap_1","text":"Max had heard that the new restaurant was the best in town. When his meal finally arrived, it was small and lukewarm, and he left feeling ____.","answer":"disappointed"},{"passageId":"u3_34_disappointed_passage_2","contextId":"u3_34_disappointed_gap_2","text":"The poster promised enormous portions and a friendly atmosphere. The reality was a tiny plate of rice and a rude waiter, so the guests were ____ with their evening.","answer":"disappointed"}],"contextDependentParaphrases":[],"wrongParaphrases":["worn out","held up","sold out"],"misleadingDistractors":["angry because someone was rude","tired because of too much work","worried because something is dangerous"]}]'::jsonb,'["disappoint","disappointing","disappointment"]'::jsonb,'["feel disappointed","bitterly disappointed","slightly disappointed"]'::jsonb,'live'),
('vocab_inconvenient','inconvenient','adjective','causing difficulty or extra trouble because it does not suit your needs','[{"senseId":"inconvenient_1","meaning":"causing difficulty or extra trouble because it does not suit your needs","acceptedParaphrases":["not suitable","troublesome"],"masteryContexts":[{"contextId":"u3_35_inconvenient_meaning","text":"The cafe is open only from ten to two, which is inconvenient for people who finish work at five.","meaning":"causing difficulty because of the time","wrongMeanings":["uncomfortable because the chairs are hard","unpleasant because of the smell","unsafe because of the traffic"]},{"contextId":"u3_35_inconvenient_paraphrase","text":"Having no parking near the market is inconvenient for shoppers with heavy bags.","meaning":"not suitable and causing extra trouble","wrongMeanings":["unpopular because the food is plain","unfair because the prices are high","unhealthy because the food is fried"]}],"situationDistractors":["The chairs were soft, the room was warm, and the music was gentle.","The restaurant was right next to the station and open until midnight.","Buses stopped outside the cafe every five minutes all day.","The cook made a pot of tomato soup.","The restaurant’s walls were painted yellow.","He asked for the bill and paid in cash."],"gapDistractors":[{"contextId":"u3_35_inconvenient_gap_1","answer":"inconvenient","wrong":["uncomfortable","generous","punctual"]},{"contextId":"u3_35_inconvenient_gap_2","answer":"inconvenient","wrong":["uncomfortable","dishonest","delicious"]},{"contextId":"u3_35_inconvenient_gap_3","answer":"inconvenient","wrong":["dishonest","delicious","generous"]}],"spellingErrors":["inconvienent","inconvinient","inconveniant","inconvenint","incovenient","inconvenent"],"wordFamilyForms":[{"form":"inconvenient","partOfSpeech":"adjective","example":"The cafe is open only from ten to two, which is inconvenient for office workers.","pedagogicallyUseful":true},{"form":"inconvenience","partOfSpeech":"noun","example":"We apologise for any inconvenience caused by the closure of the kitchen.","pedagogicallyUseful":true,"altExample":"The long queue was an inconvenience for people who only had a short lunch break."},{"form":"inconveniently","partOfSpeech":"adverb","example":"The bus stop is inconveniently far from the restaurant.","pedagogicallyUseful":true,"altExample":"The cafe opens inconveniently late for workers who start at seven."}],"masteryPassages":[{"passageId":"u3_35_inconvenient_passage_1","contextId":"u3_35_inconvenient_gap_1","text":"The restaurant has wonderful food, but it is in the middle of a forest, an hour from the nearest town. For people without a car, the location is very ____.","answer":"inconvenient"},{"passageId":"u3_35_inconvenient_passage_2","contextId":"u3_35_inconvenient_gap_2","text":"The shop opens at ten and closes at three, when most people are still at work. Many customers say these hours are ____ for them.","answer":"inconvenient"}],"contextDependentParaphrases":[],"wrongParaphrases":["uncomfortable","unfriendly","unclean"],"misleadingDistractors":["not physically comfortable to sit in","not clean enough to use","not friendly to customers"]}]'::jsonb,'["inconvenience","inconveniently"]'::jsonb,'["inconvenient time","rather inconvenient","inconvenient location"]'::jsonb,'live'),
('vocab_excellent','excellent','adjective','of a very high standard, much better than most others','[{"senseId":"excellent_1","meaning":"of a very high standard, much better than most others","acceptedParaphrases":["outstanding","first-class"],"masteryContexts":[{"contextId":"u3_36_excellent_meaning","text":"The reviews describe the service as excellent and the food as fresh and well cooked.","meaning":"of a very high standard","wrongMeanings":["acceptable but nothing special","slow and sometimes unfriendly","cheap and quick to arrive"]},{"contextId":"u3_36_excellent_paraphrase","text":"The chef received an award for his excellent cooking.","meaning":"much better than most","wrongMeanings":["plain and easy to copy","expensive and hard to find","unusual and hard to explain"]}],"situationDistractors":["The soup was lukewarm, and the service was slow but acceptable.","The meal was average: neither good nor bad.","Nothing on the menu stood out, and most diners forgot the evening quickly.","The restaurant opened at noon and closed at ten.","The waiter carried the plates on a large tray.","There were fifteen tables in the main room."],"gapDistractors":[{"contextId":"u3_36_excellent_gap_1","answer":"excellent","wrong":["terrible","careless","rude"]},{"contextId":"u3_36_excellent_gap_2","answer":"excellent","wrong":["terrible","tasteless","disgusting"]},{"contextId":"u3_36_excellent_gap_3","answer":"excellent","wrong":["terrible","plain","cold"]}],"spellingErrors":["excelent","exellent","excellant","excellint","ecxellent","excelllent"],"wordFamilyForms":[{"form":"excellent","partOfSpeech":"adjective","example":"The reviews describe the food as excellent and the staff as friendly.","pedagogicallyUseful":true},{"form":"excel","partOfSpeech":"verb","example":"Some students excel at science but find cooking difficult.","pedagogicallyUseful":true,"altExample":"Italian chefs often excel at making fresh pasta."},{"form":"excellence","partOfSpeech":"noun","example":"The hotel is famous for the excellence of its breakfast buffet.","pedagogicallyUseful":true,"altExample":"The school restaurant won an award for excellence in student cooking."}],"masteryPassages":[{"passageId":"u3_36_excellent_passage_1","contextId":"u3_36_excellent_gap_1","text":"Tourists often travel across the city to eat at the small family restaurant. Its soup is so ____ that people queue in the rain for a table.","answer":"excellent"},{"passageId":"u3_36_excellent_passage_2","contextId":"u3_36_excellent_gap_2","text":"The judges tasted twenty dishes at the cooking competition. They gave the highest marks to Li Na, whose fish curry was ____ in every way.","answer":"excellent"}],"contextDependentParaphrases":[],"wrongParaphrases":["ordinary","average","acceptable"],"misleadingDistractors":["good enough to be acceptable","different from most others","expensive for what you get"]}]'::jsonb,'["excel","excellence"]'::jsonb,'["excellent service","excellent value","absolutely excellent"]'::jsonb,'live'),
('vocab_polite','polite','adjective','behaving in a respectful way that shows good manners','[{"senseId":"polite_1","meaning":"behaving in a respectful way that shows good manners","acceptedParaphrases":["courteous","well-mannered"],"masteryContexts":[{"contextId":"u3_37_polite_meaning","text":"The polite waiter thanked us for coming and held the door open.","meaning":"showing good manners and respect","wrongMeanings":["quick at serving every table","friendly with the owner only","careful about keeping the room clean"]},{"contextId":"u3_37_polite_paraphrase","text":"It is polite to say thank you to the person who brings your food.","meaning":"showing respect and good manners","wrongMeanings":["sensible to do when you pay","necessary by law","popular among young people"]}],"situationDistractors":["The waiter shouted at the customer and threw the menu on the table.","The guests talked loudly and rudely about the food while the cook was listening.","He interrupted the manager three times and walked away without a word.","The chef put on his apron and washed his hands.","The restaurant has red tablecloths and candles.","The bill was paid by credit card."],"gapDistractors":[{"contextId":"u3_37_polite_gap_1","answer":"polite","wrong":["curious","hungry","proud"]},{"contextId":"u3_37_polite_gap_2","answer":"polite","wrong":["expensive","tired","hungry"]},{"contextId":"u3_37_polite_gap_3","answer":"polite","wrong":["famous","jealous","curious"]}],"spellingErrors":["polit","poilte","pollite","polight","polyte","pollight"],"wordFamilyForms":[{"form":"polite","partOfSpeech":"adjective","example":"It is polite to say thank you to the person who brings your food.","pedagogicallyUseful":true},{"form":"politely","partOfSpeech":"adverb","example":"The waiter politely asked us to move to a larger table.","pedagogicallyUseful":true,"altExample":"She politely refused a second helping of dessert."},{"form":"politeness","partOfSpeech":"noun","example":"Staff are trained in politeness, so they always greet customers warmly.","pedagogicallyUseful":true,"altExample":"The customers praised the politeness of the young waiter."}],"masteryPassages":[{"passageId":"u3_37_polite_passage_1","contextId":"u3_37_polite_gap_1","text":"The customer was angry about the long wait, but the manager stayed calm. He spoke quietly, said sorry twice and was extremely ____ throughout the conversation.","answer":"polite"},{"passageId":"u3_37_polite_passage_2","contextId":"u3_37_polite_gap_2","text":"In many cultures, children are taught to say please and thank you from an early age. Parents say that these habits help children become ____ adults.","answer":"polite"}],"contextDependentParaphrases":[],"wrongParaphrases":["impatient","careless","talkative"],"misleadingDistractors":["quick and efficient in serving food","friendly and talkative with friends","formal and strict about rules"]}]'::jsonb,'["politely","politeness"]'::jsonb,'["very polite","perfectly polite","polite reply"]'::jsonb,'live'),
('vocab_helpful','helpful','adjective','willing to help, or useful for solving a problem','[{"senseId":"helpful_1","meaning":"willing to help, or useful for solving a problem","acceptedParaphrases":["willing to help","useful"],"masteryContexts":[{"contextId":"u3_38_helpful_meaning","text":"The shop assistant was very helpful and explained which cheese goes best with each biscuit.","meaning":"willing to give useful help","wrongMeanings":["pleased to sell the most expensive item","quick to give the bill","careful to avoid answering"]},{"contextId":"u3_38_helpful_paraphrase","text":"The website has a helpful map that shows where each food stall is located.","meaning":"useful for finding what you need","wrongMeanings":["colourful but difficult to read","old and no longer correct","expensive but badly made"]}],"situationDistractors":["The waiter ignored our questions and walked away.","Nobody at the information desk could explain the menu, and they would not try.","The assistant said it was not her job to answer and went back to her phone.","The chef cooked the fish for ten minutes.","The restaurant has a garden at the back.","The tickets were printed on blue paper."],"gapDistractors":[{"contextId":"u3_38_helpful_gap_1","answer":"helpful","wrong":["punctual","famous","nervous"]},{"contextId":"u3_38_helpful_gap_2","answer":"helpful","wrong":["careless","boring","famous"]},{"contextId":"u3_38_helpful_gap_3","answer":"helpful","wrong":["careless","famous","nervous"]}],"spellingErrors":["helpfull","helpfal","helfull","helpfool","halpful","helppful"],"wordFamilyForms":[{"form":"helpful","partOfSpeech":"adjective","example":"The staff in the cafe were friendly and helpful.","pedagogicallyUseful":true},{"form":"help","partOfSpeech":"verb","example":"Can you help me choose a dish from this long menu?","pedagogicallyUseful":true,"altExample":"The staff are always ready to help customers who cannot decide."},{"form":"unhelpful","partOfSpeech":"adjective","example":"The unhelpful waiter did not explain a single dish on the menu.","pedagogicallyUseful":true,"altExample":"The sign was unhelpful because it did not show the opening times."}],"masteryPassages":[{"passageId":"u3_38_helpful_passage_1","contextId":"u3_38_helpful_gap_1","text":"I could not read the menu because it was written in a language I did not know. Luckily, the waiter was extremely ____ and translated every dish for me.","answer":"helpful"},{"passageId":"u3_38_helpful_passage_2","contextId":"u3_38_helpful_gap_2","text":"Before the cooking exam, the teacher gave us a ____ list of tips. It explained how to measure ingredients and how to save time in the kitchen.","answer":"helpful"}],"contextDependentParaphrases":[],"wrongParaphrases":["ready to leave","keen to win","afraid to ask"],"misleadingDistractors":["pleased to see customers again","good at making food quickly","careful with money"]}]'::jsonb,'["help","unhelpful"]'::jsonb,'["extremely helpful","helpful staff","helpful advice"]'::jsonb,'live'),
('vocab_recommendation','recommendation','noun','a suggestion about what is good or what to do','[{"senseId":"recommendation_1","meaning":"a suggestion about what is good or what to do","acceptedParaphrases":["suggestion","advice"],"masteryContexts":[{"contextId":"u3_39_recommendation_meaning","text":"We booked the table on the recommendation of a friend who had eaten there twice.","meaning":"a suggestion that something is good","wrongMeanings":["a complaint about something bad","an order to do something","a promise to return"]},{"contextId":"u3_39_recommendation_paraphrase","text":"The waiter gave us a recommendation for dessert, and the chocolate cake was delicious.","meaning":"advice about what to choose","wrongMeanings":["a bill for something eaten","a warning about something dangerous","a list of everything on the menu"]}],"situationDistractors":["The customer wrote a long complaint about the cold soup.","The manager ordered the staff to wear uniforms.","The guests paid the bill and left a tip.","The waiter wiped the menu and put it back.","The cook peeled carrots into a bowl.","The restaurant opens on Mondays."],"gapDistractors":[{"contextId":"u3_39_recommendation_gap_1","answer":"recommendation","wrong":["complaint","argument","invoice"]},{"contextId":"u3_39_recommendation_gap_2","answer":"recommendation","wrong":["complaint","joke","photo"]},{"contextId":"u3_39_recommendation_gap_3","answer":"recommendation","wrong":["warning","receipt","bill"]}],"spellingErrors":["recomendation","reccomendation","recommendasion","recommedation","recommandation","recomendacion"],"wordFamilyForms":[{"form":"recommendation","partOfSpeech":"noun","example":"We chose this restaurant on the recommendation of a friend.","pedagogicallyUseful":true},{"form":"recommend","partOfSpeech":"verb","example":"Could you recommend a quiet restaurant near the station?","pedagogicallyUseful":true,"altExample":"I strongly recommend the chocolate cake at that cafe."},{"form":"recommended","partOfSpeech":"adjective","example":"The label gives the recommended amount for one person.","pedagogicallyUseful":true,"altExample":"The recommended cooking time is twenty minutes."}],"masteryPassages":[{"passageId":"u3_39_recommendation_passage_1","contextId":"u3_39_recommendation_gap_1","text":"Tourists often ask hotel staff where to eat. On the ____ of the receptionist, we tried a small noodle shop, and it was the best meal of our trip.","answer":"recommendation"},{"passageId":"u3_39_recommendation_passage_2","contextId":"u3_39_recommendation_gap_2","text":"I could not decide what to order, so I asked the waiter for a ____. He told me the lamb curry was the best dish on the menu, and he was right.","answer":"recommendation"}],"contextDependentParaphrases":[],"wrongParaphrases":["complaint","refund","order"],"misleadingDistractors":["a complaint about poor service","a bill for a meal","a rule that everyone must follow"]}]'::jsonb,'["recommend","recommended"]'::jsonb,'["strong recommendation","personal recommendation","make recommendation"]'::jsonb,'live'),
('vocab_informative','informative','adjective','giving a lot of useful facts','[{"senseId":"informative_1","meaning":"giving a lot of useful facts","acceptedParaphrases":["full of facts","instructive"],"masteryContexts":[{"contextId":"u3_40_informative_meaning","text":"The museum’s food exhibition was very informative, with clear facts about how rice is grown.","meaning":"giving a lot of useful facts","wrongMeanings":["exciting and full of surprises","long and difficult to follow","cheap and open to everyone"]},{"contextId":"u3_40_informative_paraphrase","text":"The label is informative because it lists every ingredient and the amount of sugar in each portion.","meaning":"giving clear and useful facts","wrongMeanings":["colourful and attractive to children","short and without any detail","difficult to read from far away"]}],"situationDistractors":["The leaflet had a lovely picture of a cake but no facts at all.","The poster was colourful, but nobody could say what it was about.","The speaker told funny stories for an hour and gave no facts about the food.","The chef washed the pans after the lesson.","The class visited the market on Tuesday.","The tour guide wore a green jacket."],"gapDistractors":[{"contextId":"u3_40_informative_gap_1","answer":"informative","wrong":["careless","crowded","tasteless"]},{"contextId":"u3_40_informative_gap_2","answer":"informative","wrong":["noisy","sticky","crowded"]},{"contextId":"u3_40_informative_gap_3","answer":"informative","wrong":["careless","tasteless","dishonest"]}],"spellingErrors":["informitive","infomative","informativ","enformative","informatif","informatuve"],"wordFamilyForms":[{"form":"informative","partOfSpeech":"adjective","example":"The guide to local food was informative, with clear facts about every dish.","pedagogicallyUseful":true},{"form":"inform","partOfSpeech":"verb","example":"Please inform the waiter if you have any special dietary needs.","pedagogicallyUseful":true,"altExample":"The school will inform parents about the new lunch menu by email."},{"form":"information","partOfSpeech":"noun","example":"The menu gives clear information about every dish.","pedagogicallyUseful":true,"altExample":"Tourists can find information about local restaurants at the station."}],"masteryPassages":[{"passageId":"u3_40_informative_passage_1","contextId":"u3_40_informative_gap_1","text":"Before the school trip to the farm, the teacher handed out a leaflet. It was short but very ____: it explained where milk comes from and how cheese is made.","answer":"informative"},{"passageId":"u3_40_informative_passage_2","contextId":"u3_40_informative_gap_2","text":"Tom did not enjoy the cooking show at first. However, he found it ____, because he learned why bread needs time to rise.","answer":"informative"}],"contextDependentParaphrases":[],"wrongParaphrases":["entertaining","confusing","misleading"],"misleadingDistractors":["exciting and enjoyable to watch","long and difficult to follow","short and without any detail"]}]'::jsonb,'["inform","information"]'::jsonb,'["highly informative","informative leaflet","very informative"]'::jsonb,'live')
